    pub fn try_new(value: &str) -> Option<Self> {
        match Self::from_wire(value) {
            Self::Unknown(_) => None,
            known => Some(known),
        }
    }

    pub fn is_standard(&self) -> bool {
        self.descriptor().is_some()
    }

    pub fn descriptor(&self) -> Option<&'static EventKindDescriptor> {
        EVENT_KIND_DESCRIPTORS
            .binary_search_by_key(&self.as_str(), |descriptor| descriptor.kind)
            .ok()
            .map(|index| &EVENT_KIND_DESCRIPTORS[index])
    }

    pub fn registry_category(&self) -> Option<EventRegistryCategory> {
        self.descriptor().map(|descriptor| descriptor.category)
    }

    pub fn effect_descriptor(&self) -> Option<&'static EventEffectDescriptor> {
        self.descriptor()
            .and_then(|descriptor| descriptor.effect.as_ref())
    }

    pub fn effect_ownership(&self) -> Option<EventEffectOwnership> {
        self.effect_descriptor()
            .map(|descriptor| descriptor.ownership)
    }

    pub fn product_class(&self) -> EventProductClass {
        event_product_class(self)
    }

    /// Whether the registry declares this kind an input to the shared product
    /// reducer. Unregistered kinds are never reducer inputs.
    pub fn is_reducer_input(&self) -> bool {
        self.descriptor()
            .is_some_and(|descriptor| descriptor.reducer_input)
    }

    pub fn wire_scope(&self) -> EventWireScope {
        self.descriptor()
            .map(|descriptor| descriptor.wire_scope)
            .unwrap_or_else(|| event_wire_scope(self.as_str()))
    }
